using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
using System.IO;

public class SceneBuilder
{
    public static void Build()
    {
        string scenePath = "Assets/Scenes/Credit/CreditScene.unity";
        // Try to move existing scene if it's at old path
        if (File.Exists("Assets/Scenes/CreditScene.unity"))
        {
            AssetDatabase.MoveAsset("Assets/Scenes/CreditScene.unity", scenePath);
        }

        var scene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);

        foreach (var root in scene.GetRootGameObjects())
        {
            if (root.name != "Directional Light" && root.name != "Main Camera")
            {
                Object.DestroyImmediate(root);
            }
        }

        if (Object.FindObjectOfType<UnityEngine.EventSystems.EventSystem>() == null)
        {
            var esObj = new GameObject("EventSystem");
            esObj.AddComponent<UnityEngine.EventSystems.EventSystem>();
            esObj.AddComponent<UnityEngine.EventSystems.StandaloneInputModule>();
        }

        GameObject canvasObj = new GameObject("Canvas");
        Canvas canvas = canvasObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.ScreenSpaceOverlay;
        CanvasScaler scaler = canvasObj.AddComponent<CanvasScaler>();
        scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
        scaler.referenceResolution = new Vector2(1920, 1080);
        canvasObj.AddComponent<GraphicRaycaster>();

        GameObject bgObj = new GameObject("Background");
        bgObj.transform.SetParent(canvasObj.transform, false);
        Image bgImg = bgObj.AddComponent<Image>();
        RectTransform bgRect = bgObj.GetComponent<RectTransform>();
        bgRect.anchorMin = Vector2.zero;
        bgRect.anchorMax = Vector2.one;
        bgRect.sizeDelta = Vector2.zero;

        Sprite bgSprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Scenes/Credit/CreditBg.png");
        if (bgSprite == null) {
            Texture2D tex = AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Scenes/Credit/CreditBg.png");
            if(tex != null) {
                string path = AssetDatabase.GetAssetPath(tex);
                TextureImporter importer = (TextureImporter)TextureImporter.GetAtPath(path);
                importer.textureType = TextureImporterType.Sprite;
                importer.SaveAndReimport();
                bgSprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Scenes/Credit/CreditBg.png");
            }
        }
        bgImg.sprite = bgSprite;

        string[] imgPaths = new string[] {
            "Assets/Scenes/Credit/NameTagBoard.png",
            "Assets/Scenes/Credit/ArrowButton.png",
            "Assets/Scenes/Credit/BackButton.png"
        };
        foreach(var p in imgPaths) {
            TextureImporter importer = (TextureImporter)TextureImporter.GetAtPath(p);
            if(importer != null && importer.textureType != TextureImporterType.Sprite) {
                importer.textureType = TextureImporterType.Sprite;
                importer.SaveAndReimport();
            }
        }

        GameObject titleObj = new GameObject("TitleText");
        titleObj.transform.SetParent(canvasObj.transform, false);
        TextMeshProUGUI titleText = titleObj.AddComponent<TextMeshProUGUI>();
        titleText.text = "CREDIT";
        titleText.fontSize = 120;
        titleText.alignment = TextAlignmentOptions.Center;
        titleText.fontStyle = FontStyles.Bold;
        titleText.color = new Color(0.3f, 0.15f, 0.05f);
        RectTransform titleRect = titleObj.GetComponent<RectTransform>();
        titleRect.anchorMin = new Vector2(0.5f, 1);
        titleRect.anchorMax = new Vector2(0.5f, 1);
        titleRect.pivot = new Vector2(0.5f, 1);
        titleRect.anchoredPosition = new Vector2(0, -50);
        titleRect.sizeDelta = new Vector2(600, 150);

        GameObject backBtnObj = new GameObject("BackButton");
        backBtnObj.transform.SetParent(canvasObj.transform, false);
        Image backBtnImg = backBtnObj.AddComponent<Image>();
        backBtnImg.sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Scenes/Credit/BackButton.png");
        Button backBtn = backBtnObj.AddComponent<Button>();
        RectTransform backBtnRect = backBtnObj.GetComponent<RectTransform>();
        backBtnRect.anchorMin = new Vector2(0, 1);
        backBtnRect.anchorMax = new Vector2(0, 1);
        backBtnRect.pivot = new Vector2(0, 1);
        backBtnRect.anchoredPosition = new Vector2(50, -50);
        backBtnRect.sizeDelta = new Vector2(250, 100);

        GameObject containerObj = new GameObject("SlideContainer");
        containerObj.transform.SetParent(canvasObj.transform, false);
        RectTransform containerRect = containerObj.AddComponent<RectTransform>();
        containerRect.anchorMin = new Vector2(0.5f, 0.5f);
        containerRect.anchorMax = new Vector2(0.5f, 0.5f);
        containerRect.anchoredPosition = new Vector2(0, -50);
        containerRect.sizeDelta = new Vector2(800, 600);
        CanvasGroup canvasGroup = containerObj.AddComponent<CanvasGroup>();

        GameObject photoObj = new GameObject("PhotoImage");
        photoObj.transform.SetParent(containerObj.transform, false);
        Image photoImg = photoObj.AddComponent<Image>();
        photoImg.color = new Color(0,0,0,0.5f);
        RectTransform photoRect = photoObj.GetComponent<RectTransform>();
        photoRect.anchoredPosition = new Vector2(0, 100);
        photoRect.sizeDelta = new Vector2(300, 300);

        GameObject boardObj = new GameObject("NameTagBoard");
        boardObj.transform.SetParent(containerObj.transform, false);
        Image boardImg = boardObj.AddComponent<Image>();
        boardImg.sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Scenes/Credit/NameTagBoard.png");
        RectTransform boardRect = boardObj.GetComponent<RectTransform>();
        boardRect.anchoredPosition = new Vector2(0, -150);
        boardRect.sizeDelta = new Vector2(600, 180);

        GameObject nameObj = new GameObject("NameText");
        nameObj.transform.SetParent(boardObj.transform, false);
        TextMeshProUGUI nameTMP = nameObj.AddComponent<TextMeshProUGUI>();
        nameTMP.text = "Member Name";
        nameTMP.fontSize = 50;
        nameTMP.alignment = TextAlignmentOptions.Center;
        nameTMP.color = new Color(0.2f, 0.1f, 0.05f);
        RectTransform nameRect = nameObj.GetComponent<RectTransform>();
        nameRect.anchoredPosition = new Vector2(0, 20);
        nameRect.sizeDelta = new Vector2(500, 70);

        GameObject infoObj = new GameObject("InfoText");
        infoObj.transform.SetParent(boardObj.transform, false);
        TextMeshProUGUI infoTMP = infoObj.AddComponent<TextMeshProUGUI>();
        infoTMP.text = "123456789";
        infoTMP.fontSize = 40;
        infoTMP.alignment = TextAlignmentOptions.Center;
        infoTMP.color = new Color(0.3f, 0.15f, 0.1f);
        RectTransform infoRect = infoObj.GetComponent<RectTransform>();
        infoRect.anchoredPosition = new Vector2(0, -40);
        infoRect.sizeDelta = new Vector2(500, 60);

        GameObject prevBtnObj = new GameObject("PrevButton");
        prevBtnObj.transform.SetParent(containerObj.transform, false);
        Image prevBtnImg = prevBtnObj.AddComponent<Image>();
        prevBtnImg.sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Scenes/Credit/ArrowButton.png");
        Button prevBtn = prevBtnObj.AddComponent<Button>();
        RectTransform prevBtnRect = prevBtnObj.GetComponent<RectTransform>();
        prevBtnRect.anchoredPosition = new Vector2(-450, -150);
        prevBtnRect.sizeDelta = new Vector2(120, 120);
        prevBtnRect.localScale = new Vector3(-1, 1, 1);

        GameObject nextBtnObj = new GameObject("NextButton");
        nextBtnObj.transform.SetParent(containerObj.transform, false);
        Image nextBtnImg = nextBtnObj.AddComponent<Image>();
        nextBtnImg.sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Scenes/Credit/ArrowButton.png");
        Button nextBtn = nextBtnObj.AddComponent<Button>();
        RectTransform nextBtnRect = nextBtnObj.GetComponent<RectTransform>();
        nextBtnRect.anchoredPosition = new Vector2(450, -150);
        nextBtnRect.sizeDelta = new Vector2(120, 120);

        CreditSlideController controller = canvasObj.AddComponent<CreditSlideController>();
        var serializedObject = new SerializedObject(controller);
        serializedObject.FindProperty("photoImage").objectReferenceValue = photoImg;
        serializedObject.FindProperty("nameText").objectReferenceValue = nameTMP;
        serializedObject.FindProperty("infoText").objectReferenceValue = infoTMP;
        serializedObject.FindProperty("nextButton").objectReferenceValue = nextBtn;
        serializedObject.FindProperty("prevButton").objectReferenceValue = prevBtn;
        serializedObject.FindProperty("backButton").objectReferenceValue = backBtn;
        serializedObject.FindProperty("slideContainer").objectReferenceValue = containerRect;
        serializedObject.FindProperty("slideCanvasGroup").objectReferenceValue = canvasGroup;
        serializedObject.ApplyModifiedProperties();

        EditorSceneManager.SaveScene(scene);
    }
}
